```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitEarnedOrLoss;

  Transaction({required this.coinName, required this.datetime, required this.profitEarnedOrLoss});
}

List<Transaction> sortTransactionsByAverageProfit(List<Transaction> transactions) {
  return transactions.sort((a, b) => a.profitEarnedOrLoss.compareTo(b.profitEarnedOrLoss));
}

List<Transaction> sortTransactionsByAverageLoss(List<Transaction> transactions) {
  return transactions.sort((a, b) => -a.profitEarnedOrLoss.compareTo(b.profitEarnedOrLoss));
}

List<String> getTopThreeCoinsWithHighestAverageProfit(List<Transaction> transactions) {
  List<Transaction> sortedTransactions = sortTransactionsByAverageProfit(transactions);
  return sortedTransactions.sublist(0, 3).map((transaction) => transaction.coinName).toList();
}

List<String> getTopThreeCoinsWithHighestAverageLoss(List<Transaction> transactions) {
  List<Transaction> sortedTransactions = sortTransactionsByAverageLoss(transactions);
  return sortedTransactions.sublist(0, 3).map((transaction) => transaction.coinName).toList();
}

