Here's a MATLAB code that can identify the tense of a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = split(sentence);

    % Initialize a dictionary with the tense names and their corresponding regular expressions
    tenses = {
        'Present Simple': r'^(\w+)\s+is\s+(\w+)$',
        'Present Continuous': r'^(\w+)\s+is\s+being\s+(\w+)$',
        'Present Perfect': r'^(\w+)\s+has\s+been\s+(\w+)$',
        'Present Conditional': r'^(\w+)\s+would\s+(\w+)$',
        'Past Simple': r'^(\w+)\s+was\s+(\w+)$',
        'Past Continuous': r'^(\w+)\s+was\s+being\s+(\w+)$',
        'Past Perfect': r'^(\w+)\s+had\s+been\s+(\w+)$',
        'Future Simple': r'^(\w+)\s+will\s+(\w+)$',
        'Future Continuous': r'^(\w+)\s+will\s+be\s+(\w+)$',
        'Future Perfect': r'^(\w+)\s+will\s+have\s+been\s+(\w+)$',
        'Modals': r'^(\w+)\s+(?:can|could|may|might|must|ought|shall|should|will|would)$'
    };

    % Iterate through the tenses and check if any of them match the sentence
    for i = 1:length(tenses)
        pattern = tenses{i}(1);
        if regexp(words, pattern, 'match')
            tense = tenses{i}(2);
            break;
        end
    end
end

